{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Living systematic review and network meta-analysis.",
      "reason": "The provided evidence includes the phrase identifying the work as a 'living systematic review' but it does not explicitly show that this phrase is part of the article title."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "In this living systematic review and network meta-analysis we compare the effects of drug treatments for covid-19.",
      "reason": "The evidence specifies the main objective/review question component: comparing the effects of drug treatments for covid-19."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "This article is a living systematic review that will be updated to reflect emerging evidence. This is the fifth version of the original article published on 30 July 2020 ( BMJ 2020;370:m2980), and previous versions can be found as data supplements.",
      "reason": "The evidence describes living-review/update status and that it is the fifth version, but it is not shown to be specifically included in the title (as required for this item)."
    }
  ],
  "confidence": 52
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Despite global efforts to identify effective interventions for the prevention and treatment of covid-19, which have resulted in approximately 3000 trials completed or underway, 2 evidence for effective treatment remains limited. Summarising the rapidly growing evidence base has been a challenge. 3",
      "reason": "The current state of knowledge is described (evidence remains limited despite many trials) and the uncertainty/challenge (rapidly growing evidence base) is stated."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Living systematic reviews deal with the main limitation of traditional reviews-that of providing an overview of the relevant evidence only at a specific time. 4 This is crucial in the context of covid-19, in which the best evidence is constantly changing.",
      "reason": "The importance/need is explained by linking the living approach to the changing evidence in covid-19."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_22",
      "quote": "To date, we are aware of two other similar efforts to ours. 42 43",
      "reason": "The existence of similar efforts is acknowledged, but the need for the current review is not fully explained with detailed comparison to specific prior systematic reviews (e.g., which reviews and how they differ)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No proposed mechanism of action for interventions is described in the retrieved introduction/rationale evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence in the retrieved material of a logic model for complex interventions/delivery contexts."
    }
  ],
  "confidence": 68
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "To compare the effects of treatments for coronavirus disease 2019 (covid-19).",
      "reason": "The review objective/question is explicitly stated as a comparison of treatments for covid-19."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Randomised clinical trials in which people with suspected, probable, or confirmed covid-19 were randomised to drug treatment or to standard care or placebo.",
      "reason": "The evidence indicates a planned type of comparison (drug treatment vs standard care/placebo) and the population (suspected/probable/confirmed covid-19), but it does not clearly present the planned comparisons using a full PICO (or appropriate variant) framework."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "Weincluded randomised clinical trials in people with suspected, probable, or confirmed covid-19 that compared drugs for treatment against one another or against no intervention, placebo, or standard care. We included trials regardless of publication status (peer reviewed, in press, or preprint) or language. No restrictions were applied based on severity of illness or setting, and we included trials of Chinese medicines if the drug comprised one or more specific molecules with a defined molecular weight dosing.\nWeexcluded randomised trials evaluating vaccination, blood products and antibody-based antiviral therapies (such as virus-specific monoclonal antibodies), nutrition, traditional Chinese herbal or alternative medicines that include more than one molecule or a molecule without specific molecular weighted dosing, and non-drugsupportive care interventions.",
      "reason": "Eligibility criteria for study design (randomised clinical trials), population (suspected/probable/confirmed COVID-19), intervention/comparator (drugs vs each other or vs no intervention/placebo/standard care), and some exclusions are specified. However, follow-up requirements are not described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "We included trials regardless of publication status (peer reviewed, in press, or preprint) or language. No restrictions were applied based on severity of illness or setting, and we included trials of Chinese medicines if the drug comprised one or more specific molecules with a defined molecular weight dosing.",
      "reason": "Dissemination characteristics (publication status and language) are explicitly addressed. The retrieved evidence does not specify dissemination year or any publication/report date restrictions."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe whether exclusions were distinguished between (a) outcomes not measured and (b) outcomes not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although eligible interventions and comparisons are described generally, the retrieved evidence does not specify the groups used in each synthesis and how they link to the comparisons in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "For that reason, we decided to report evidence on treatments for which at least 100 people were randomised or for which there were at least 20 events.",
      "reason": "A rationale is provided for a notable restriction on study eligibility/reporting (minimum randomized participants/events), tied to anticipated problems with sparse data in network meta-analysis."
    }
  ],
  "confidence": 62
}

