{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "Outcomesofinterestwereselectedbasedonimportancetopatients 18 and were informed by clinical expertise in the systematic review teamandinthelinkedguidelinepanelresponsiblefor theWHOBMJ Rapid Recommendations. 19 7 8 ... Selected outcomes included mortality (closest to 90 days), mechanical ventilation (total number of patients, over 90 days), adverse events leading to discontinuation (within 28 days), admission to hospital, length of hospital stay, duration of mechanical ventilation, and time to symptom resolution or clinical improvement.",
      "reason": "The outcomes/outcome domains for which data were sought are listed, and the selection criterion (patient importance) and source of that selection are described."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "Selected outcomes included mortality (closest to 90 days), mechanical ventilation (total number of patients, over 90 days), adverse events leading to discontinuation (within 28 days), admission to hospital, length of hospital stay, duration of mechanical ventilation, and time to symptom resolution or clinical improvement.",
      "reason": "The measurement time frame is specified for multiple outcomes (e.g., mortality closest to 90 days; mechanical ventilation over 90 days; discontinuation adverse events within 28 days; and time to symptom resolution/improvement)."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not explicitly state whether all compatible results within each outcome domain were sought (e.g., all measures/time points/analyses) or not."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PARTIAL",
      "chunk_id": "text_16",
      "quote": "We used a hierarchy for the outcome mechanical ventilation in which we preferentially used the total number of patients who received mechanical ventilation over the study. We used the number of patients ventilated at the time point that the largest number of the patients were ventilated, if the trial reported the number of patients ventilated at specific timepoints.",
      "reason": "When not all compatible results were sought (within the mechanical ventilation outcome), the selection process is described (hierarchy and timepoint choice), but no general statement is provided for all outcome domains."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "In contrast to previous iterations, for this iteration, we did not include several outcomes which the GDG did not think were critical to decision making: viral clearance (closest to 7 days, 3 days either way), time to viral clearance, intensive care unit (ICU) length of stay, and days free from mechanical ventilation (within 28 days).",
      "reason": "The manuscript reports changes from previous iterations to outcome inclusion, provides a rationale (GDG did not think outcomes were critical), and identifies the outcomes excluded."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence describes outcome selection rules (e.g., hierarchy/timepoint selection for mechanical ventilation) but does not explicitly report changes to processes for selecting results within eligible outcome domains with rationales."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "All panel members rated outcomes from 1 to 9 based on importance to individual patients (9 being most important), and we included any outcome rated 7 or higher by any panel member. Outcomesofinterestwereselectedbasedonimportancetopatients 18 and were informed by clinical expertise in the systematic review teamandinthelinkedguidelinepanelresponsiblefor theWHOBMJ Rapid Recommendations. 19 7 8",
      "reason": "The outcomes considered most important are identified through the panel rating threshold (rated 7+), and the rationale is described as importance to patients informed by the guideline panel and clinical expertise."
    }
  ],
  "confidence": 72
}

